script.setup:
// Primitive (Michael Fogleman, fogleman/primitive, MIT) ported to JavaScript: each new shape starts as the best
// of many random shapes, is hill-climbed by small mutations, and is kept with the alpha-blended color that most
// reduces the RMS error against the target (core.go computeColor / differencePartial, worker.go, optimize.go).
// The search runs on a 256px copy like Primitive's -r 256; accepted shapes are redrawn as vectors at screen size.
const gl = ctx.gl;
const bitmap = await createImageBitmap(await (await fetch(ctx.assets["great-wave.jpg"])).blob());

// Target: resize.Thumbnail(256, 256) and the average color as background (main.go, AverageImageColor).
const SIZE = 256;
const iw = bitmap.width, ih = bitmap.height;
const W = iw >= ih ? SIZE : Math.max(1, Math.trunc((SIZE * iw) / ih));
const H = iw >= ih ? Math.max(1, Math.trunc((SIZE * ih) / iw)) : SIZE;
const small = new OffscreenCanvas(W, H), sc = small.getContext("2d", { willReadFrequently: true });
sc.imageSmoothingQuality = "high";
sc.drawImage(bitmap, 0, 0, W, H);
const T = sc.getImageData(0, 0, W, H).data;
let br = 0, bg = 0, bb = 0;
for (let i = 0; i < T.length; i += 4) { br += T[i]; bg += T[i + 1]; bb += T[i + 2]; }
const BG = [Math.round(br / (W * H)), Math.round(bg / (W * H)), Math.round(bb / (W * H))];
const C = new Uint8Array(W * H * 4); // the model's current image
const N4 = W * H * 4;

const rint = (n) => Math.floor(Math.random() * n);
const clampI = (x, lo, hi) => (x < lo ? lo : x > hi ? hi : x);
const norm = () => { let u = 0; while (u === 0) u = Math.random(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random()); };
const nudge = () => Math.trunc(norm() * 16); // int(rnd.NormFloat64()*16)

// ---- scanlines (scanline.go): flat triples y, x1, x2 ----
const LY = new Int32Array(8192), LA = new Int32Array(8192), LB = new Int32Array(8192);
let nl = 0;
const line = (y, a, b) => { if (nl < 8192) { LY[nl] = y; LA[nl] = a; LB[nl] = b; nl++; } };
function crop() { // cropScanlines
  let j = 0;
  for (let i = 0; i < nl; i++) {
    const y = LY[i]; let a = LA[i], b = LB[i];
    if (y < 0 || y >= H || a >= W || b < 0) continue;
    a = clampI(a, 0, W - 1); b = clampI(b, 0, W - 1);
    if (a > b) continue;
    LY[j] = y; LA[j] = a; LB[j] = b; j++;
  }
  nl = j;
}

// ---- shapes (triangle.go, rectangle.go, ellipse.go) ----
const TRI = 1, RECT = 2, ELL = 3, CIRC = 4, RRECT = 5, RELL = 7;
const COMBO_TYPES = [TRI, RECT, ELL, CIRC, RRECT, RELL];
const deg = (r) => (r * 180) / Math.PI, rad = (d) => (d * Math.PI) / 180;
function triValid(s) {
  const ang = (ax, ay, bx, by, cx, cy) => {
    let x1 = bx - ax, y1 = by - ay, x2 = cx - ax, y2 = cy - ay;
    const d1 = Math.hypot(x1, y1), d2 = Math.hypot(x2, y2);
    x1 /= d1; y1 /= d1; x2 /= d2; y2 /= d2;
    return deg(Math.acos(x1 * x2 + y1 * y2));
  };
  const a1 = ang(s.x1, s.y1, s.x2, s.y2, s.x3, s.y3), a2 = ang(s.x2, s.y2, s.x1, s.y1, s.x3, s.y3), a3 = 180 - a1 - a2;
  return a1 > 15 && a2 > 15 && a3 > 15;
}
function mutate(s) {
  const m = 16;
  switch (s.t) {
    case TRI:
      for (let guard = 0; guard < 1000; guard++) {
        const k = rint(3);
        if (k === 0) { s.x1 = clampI(s.x1 + nudge(), -m, W - 1 + m); s.y1 = clampI(s.y1 + nudge(), -m, H - 1 + m); }
        else if (k === 1) { s.x2 = clampI(s.x2 + nudge(), -m, W - 1 + m); s.y2 = clampI(s.y2 + nudge(), -m, H - 1 + m); }
        else { s.x3 = clampI(s.x3 + nudge(), -m, W - 1 + m); s.y3 = clampI(s.y3 + nudge(), -m, H - 1 + m); }
        if (triValid(s)) break;
      }
      break;
    case RECT:
      if (rint(2) === 0) { s.x1 = clampI(s.x1 + nudge(), 0, W - 1); s.y1 = clampI(s.y1 + nudge(), 0, H - 1); }
      else { s.x2 = clampI(s.x2 + nudge(), 0, W - 1); s.y2 = clampI(s.y2 + nudge(), 0, H - 1); }
      break;
    case ELL: case CIRC: {
      const k = rint(3);
      if (k === 0) { s.x = clampI(s.x + nudge(), 0, W - 1); s.y = clampI(s.y + nudge(), 0, H - 1); }
      else if (k === 1) { s.rx = clampI(s.rx + nudge(), 1, W - 1); if (s.t === CIRC) s.ry = s.rx; }
      else { s.ry = clampI(s.ry + nudge(), 1, H - 1); if (s.t === CIRC) s.rx = s.ry; }
      break;
    }
    case RRECT: {
      const k = rint(3);
      if (k === 0) { s.x = clampI(s.x + nudge(), 0, W - 1); s.y = clampI(s.y + nudge(), 0, H - 1); }
      else if (k === 1) { s.sx = clampI(s.sx + nudge(), 1, W - 1); s.sy = clampI(s.sy + nudge(), 1, H - 1); }
      else s.a += Math.trunc(norm() * 32);
      break;
    }
    case RELL: {
      const k = rint(3);
      if (k === 0) { s.x = Math.min(Math.max(s.x + norm() * 16, 0), W - 1); s.y = Math.min(Math.max(s.y + norm() * 16, 0), H - 1); }
      else if (k === 1) { s.rx = Math.min(Math.max(s.rx + norm() * 16, 1), W - 1); s.ry = Math.min(Math.max(s.ry + norm() * 16, 1), W - 1); }
      else s.a += norm() * 32;
      break;
    }
  }
}
function randomShape(t) {
  if (t === 0) t = COMBO_TYPES[rint(COMBO_TYPES.length)];
  switch (t) {
    case TRI: {
      const x1 = rint(W), y1 = rint(H);
      const s = { t, x1, y1, x2: x1 + rint(31) - 15, y2: y1 + rint(31) - 15, x3: x1 + rint(31) - 15, y3: y1 + rint(31) - 15 };
      mutate(s);
      return s;
    }
    case RECT: { const x1 = rint(W), y1 = rint(H); return { t, x1, y1, x2: clampI(x1 + rint(32) + 1, 0, W - 1), y2: clampI(y1 + rint(32) + 1, 0, H - 1) }; }
    case ELL: return { t, x: rint(W), y: rint(H), rx: rint(32) + 1, ry: rint(32) + 1 };
    case CIRC: { const r = rint(32) + 1; return { t, x: rint(W), y: rint(H), rx: r, ry: r }; }
    case RRECT: { const s = { t, x: rint(W), y: rint(H), sx: rint(32) + 1, sy: rint(32) + 1, a: rint(360) }; mutate(s); return s; }
    default: return { t: RELL, x: Math.random() * W, y: Math.random() * H, rx: Math.random() * 32 + 1, ry: Math.random() * 32 + 1, a: Math.random() * 360 };
  }
}
// rasterizeTriangle / Bottom / Top, verbatim integer behaviour
function triBottom(x1, y1, x2, y2, x3, y3) {
  const s1 = (x2 - x1) / (y2 - y1), s2 = (x3 - x1) / (y3 - y1);
  let ax = x1, bx = x1;
  for (let y = y1; y <= y2; y++) {
    let a = Math.trunc(ax), b = Math.trunc(bx);
    ax += s1; bx += s2;
    if (a > b) { const t = a; a = b; b = t; }
    line(y, a, b);
  }
}
function triTop(x1, y1, x2, y2, x3, y3) {
  const s1 = (x3 - x1) / (y3 - y1), s2 = (x3 - x2) / (y3 - y2);
  let ax = x3, bx = x3;
  for (let y = y3; y > y1; y--) {
    ax -= s1; bx -= s2;
    let a = Math.trunc(ax), b = Math.trunc(bx);
    if (a > b) { const t = a; a = b; b = t; }
    line(y, a, b);
  }
}
function rasterTri(x1, y1, x2, y2, x3, y3) {
  let t;
  if (y1 > y3) { t = x1; x1 = x3; x3 = t; t = y1; y1 = y3; y3 = t; }
  if (y1 > y2) { t = x1; x1 = x2; x2 = t; t = y1; y1 = y2; y2 = t; }
  if (y2 > y3) { t = x2; x2 = x3; x3 = t; t = y2; y2 = y3; y3 = t; }
  if (y2 === y3) triBottom(x1, y1, x2, y2, x3, y3);
  else if (y1 === y2) triTop(x1, y1, x2, y2, x3, y3);
  else {
    const x4 = x1 + Math.trunc(((y2 - y1) / (y3 - y1)) * (x3 - x1));
    triBottom(x1, y1, x2, y2, x4, y2);
    triTop(x2, y2, x4, y2, x3, y3);
  }
}
// Convex polygon fill at pixel centres (stands in for freetype's path rasterizer used for rotated ellipses).
const PX = new Float64Array(32), PY = new Float64Array(32);
function fillConvex(n) {
  let y0 = Infinity, y1 = -Infinity;
  for (let i = 0; i < n; i++) { y0 = Math.min(y0, PY[i]); y1 = Math.max(y1, PY[i]); }
  for (let y = Math.max(0, Math.ceil(y0 - 0.5)); y <= Math.min(H - 1, Math.floor(y1 - 0.5)); y++) {
    const yc = y + 0.5;
    let lo = Infinity, hi = -Infinity;
    for (let i = 0; i < n; i++) {
      const ax = PX[i], ay = PY[i], bx = PX[(i + 1) % n], by = PY[(i + 1) % n];
      if ((ay <= yc && by > yc) || (by <= yc && ay > yc)) {
        const x = ax + ((yc - ay) / (by - ay)) * (bx - ax);
        lo = Math.min(lo, x); hi = Math.max(hi, x);
      }
    }
    if (lo > hi) continue;
    const a = Math.max(0, Math.ceil(lo - 0.5)), b = Math.min(W - 1, Math.floor(hi - 0.5));
    if (b >= a) line(y, a, b);
  }
}
function rasterize(s) {
  nl = 0;
  switch (s.t) {
    case TRI: rasterTri(s.x1, s.y1, s.x2, s.y2, s.x3, s.y3); crop(); break;
    case RECT: {
      const x1 = Math.min(s.x1, s.x2), x2 = Math.max(s.x1, s.x2), y1 = Math.min(s.y1, s.y2), y2 = Math.max(s.y1, s.y2);
      for (let y = y1; y <= y2; y++) line(y, x1, x2);
      break;
    }
    case ELL: case CIRC: {
      const aspect = s.rx / s.ry;
      for (let dy = 0; dy < s.ry; dy++) {
        const y1 = s.y - dy, y2 = s.y + dy;
        if ((y1 < 0 || y1 >= H) && (y2 < 0 || y2 >= H)) continue;
        const w = Math.trunc(Math.sqrt(s.ry * s.ry - dy * dy) * aspect);
        const x1 = Math.max(0, s.x - w), x2 = Math.min(W - 1, s.x + w);
        if (y1 >= 0 && y1 < H) line(y1, x1, x2);
        if (y2 >= 0 && y2 < H && dy > 0) line(y2, x1, x2);
      }
      break;
    }
    case RRECT: { // RotatedRectangle.Rasterize: walk the four edges, keep min/max x per row
      const a = rad(s.a), ca = Math.cos(a), sa = Math.sin(a), hx = s.sx / 2, hy = s.sy / 2;
      const cx = [-hx, hx, hx, -hx], cy = [-hy, -hy, hy, hy], xs = [], ys = [];
      for (let i = 0; i < 4; i++) { xs.push(Math.trunc(cx[i] * ca - cy[i] * sa) + s.x); ys.push(Math.trunc(cx[i] * sa + cy[i] * ca) + s.y); }
      xs.push(xs[0]); ys.push(ys[0]);
      const miny = Math.min(...ys), maxy = Math.max(...ys), n = maxy - miny + 1;
      const mn = new Int32Array(n).fill(W), mx = new Int32Array(n);
      for (let i = 0; i < 4; i++) {
        const dx = xs[i + 1] - xs[i], dy = ys[i + 1] - ys[i];
        const count = Math.trunc(Math.hypot(dx, dy)) * 2;
        for (let j = 0; j < count; j++) {
          const t = count > 1 ? j / (count - 1) : 0;
          const xi = Math.trunc(xs[i] + dx * t), yi = Math.trunc(ys[i] + dy * t) - miny;
          if (xi < mn[yi]) mn[yi] = xi;
          if (xi > mx[yi]) mx[yi] = xi;
        }
      }
      for (let i = 0; i < n; i++) {
        const y = miny + i;
        if (y < 0 || y >= H) continue;
        const a2 = Math.max(mn[i], 0), b2 = Math.min(mx[i], W - 1);
        if (b2 >= a2) line(y, a2, b2);
      }
      break;
    }
    case RELL: {
      const a = rad(s.a), ca = Math.cos(a), sa = Math.sin(a);
      for (let i = 0; i < 32; i++) {
        const th = (i / 32) * Math.PI * 2, ex = s.rx * Math.cos(th), ey = s.ry * Math.sin(th);
        PX[i] = ex * ca - ey * sa + s.x; PY[i] = ex * sa + ey * ca + s.y;
      }
      fillConvex(32);
      break;
    }
  }
  return nl;
}

// ---- core.go: best color for the covered pixels, the blend, and the partial RMS difference ----
const col = [0, 0, 0];
function computeColor(alpha) {
  let rs = 0, gs = 0, bs = 0, count = 0;
  const a = Math.trunc((0x101 * 255) / alpha);
  for (let k = 0; k < nl; k++) {
    let i = (LY[k] * W + LA[k]) * 4;
    for (let x = LA[k]; x <= LB[k]; x++, i += 4) {
      const cr = C[i], cg = C[i + 1], cb = C[i + 2];
      rs += (T[i] - cr) * a + cr * 0x101; gs += (T[i + 1] - cg) * a + cg * 0x101; bs += (T[i + 2] - cb) * a + cb * 0x101;
      count++;
    }
  }
  if (!count) { col[0] = col[1] = col[2] = 0; return; }
  col[0] = clampI(Math.trunc(rs / count) >> 8, 0, 255);
  col[1] = clampI(Math.trunc(gs / count) >> 8, 0, 255);
  col[2] = clampI(Math.trunc(bs / count) >> 8, 0, 255);
}
// drawLines' fixed-point "over" blend with a premultiplied NRGBA source (Go image/color semantics).
let SR = 0, SG = 0, SB = 0, AM = 0;
function prepBlend(alpha) {
  SR = Math.floor((col[0] * 257 * alpha) / 255); SG = Math.floor((col[1] * 257 * alpha) / 255); SB = Math.floor((col[2] * 257 * alpha) / 255);
  AM = (65535 - alpha * 257) * 257;
}
const blend = (d, s) => Math.floor((d * AM + s * 65535) / 65535) >> 8;
const st = { score: 0 };
function energy(s, alpha) { // Worker.Energy: color, blend into a copy, differencePartial
  rasterize(s);
  computeColor(alpha);
  prepBlend(alpha);
  let total = Math.trunc((st.score * 255) ** 2 * N4);
  for (let k = 0; k < nl; k++) {
    let i = (LY[k] * W + LA[k]) * 4;
    for (let x = LA[k]; x <= LB[k]; x++, i += 4) {
      const tr = T[i], tg = T[i + 1], tb = T[i + 2], cr = C[i], cg = C[i + 1], cb = C[i + 2];
      const ar = tr - blend(cr, SR), ag = tg - blend(cg, SG), ab = tb - blend(cb, SB);
      total += ar * ar + ag * ag + ab * ab - (tr - cr) ** 2 - (tg - cg) ** 2 - (tb - cb) ** 2;
    }
  }
  return Math.sqrt(Math.max(0, total) / N4) / 255;
}
function differenceFull() {
  let total = 0;
  for (let i = 0; i < N4; i += 4) total += (T[i] - C[i]) ** 2 + (T[i + 1] - C[i + 1]) ** 2 + (T[i + 2] - C[i + 2]) ** 2;
  return Math.sqrt(total / N4) / 255;
}

// ---- optimize.go / worker.go: BestRandomState → HillClimb, best of several restarts ----
const N_RANDOM = 300, MAX_AGE = 100, RESTARTS = 3;
function* search(type, alphaSetting) {
  let best = null;
  for (let m = 0; m < RESTARTS; m++) {
    let cur = null;
    for (let i = 0; i < N_RANDOM; i++) {
      const s = randomShape(type), alpha = alphaSetting || 128;
      const e = energy(s, alpha);
      if (!cur || e < cur.e) cur = { s, alpha, e };
      yield;
    }
    // HillClimb(state, maxAge): mutate; keep improvements, reset the age on each one
    let state = { s: { ...cur.s }, alpha: cur.alpha, e: cur.e };
    for (let age = 0; age < MAX_AGE; age++) {
      const old = { s: { ...state.s }, alpha: state.alpha, e: state.e };
      mutate(state.s);
      if (!alphaSetting) state.alpha = clampI(state.alpha + rint(21) - 10, 1, 255); // State.DoMove with -a 0
      state.e = energy(state.s, state.alpha);
      if (state.e >= cur.e) state = old;
      else { cur = { s: { ...state.s }, alpha: state.alpha, e: state.e }; age = -1; }
      yield;
    }
    if (!best || cur.e < best.e) best = cur;
  }
  return best;
}

function reset() {
  for (let i = 0; i < N4; i += 4) { C[i] = BG[0]; C[i + 1] = BG[1]; C[i + 2] = BG[2]; C[i + 3] = 255; }
  st.score = differenceFull();
  Object.assign(ctx.state, { shapes: [], gen: null, credit: 1, dirty: true, replay: true });
}
function addShape(s, alpha) { // Model.Add
  rasterize(s);
  computeColor(alpha);
  prepBlend(alpha);
  for (let k = 0; k < nl; k++) {
    let i = (LY[k] * W + LA[k]) * 4;
    for (let x = LA[k]; x <= LB[k]; x++, i += 4) { C[i] = blend(C[i], SR); C[i + 1] = blend(C[i + 1], SG); C[i + 2] = blend(C[i + 2], SB); }
  }
  st.score = energyAfterAdd();
  const shape = { s, c: [col[0], col[1], col[2]], alpha };
  ctx.state.shapes.push(shape);
  return shape;
}
function energyAfterAdd() { return differenceFull(); }

// ---- display: accepted shapes redrawn as vectors at screen size (Shape.Draw, gg with scale + translate(0.5)) ----
const paint = new OffscreenCanvas(16, 16), pc = paint.getContext("2d");
function drawShape(sh, k) {
  const { s, c, alpha } = sh;
  pc.setTransform(k, 0, 0, k, 0.5 * k, 0.5 * k);
  pc.fillStyle = `rgba(${c[0]},${c[1]},${c[2]},${alpha / 255})`;
  pc.beginPath();
  switch (s.t) {
    case TRI: pc.moveTo(s.x1, s.y1); pc.lineTo(s.x2, s.y2); pc.lineTo(s.x3, s.y3); pc.closePath(); break;
    case RECT: { const x1 = Math.min(s.x1, s.x2), y1 = Math.min(s.y1, s.y2); pc.rect(x1, y1, Math.abs(s.x2 - s.x1) + 1, Math.abs(s.y2 - s.y1) + 1); break; }
    case ELL: case CIRC: pc.ellipse(s.x, s.y, s.rx, s.ry, 0, 0, Math.PI * 2); break;
    case RRECT: pc.translate(s.x, s.y); pc.rotate(rad(s.a)); pc.rect(-s.sx / 2, -s.sy / 2, s.sx, s.sy); break;
    case RELL: pc.ellipse(s.x, s.y, s.rx, s.ry, rad(s.a), 0, Math.PI * 2); break;
  }
  pc.fill();
}
function redrawAll(pw, ph) {
  if (paint.width !== pw || paint.height !== ph) { paint.width = pw; paint.height = ph; }
  pc.setTransform(1, 0, 0, 1, 0, 0);
  pc.fillStyle = `rgb(${BG[0]},${BG[1]},${BG[2]})`;
  pc.fillRect(0, 0, pw, ph);
  const k = pw / W;
  for (const sh of ctx.state.shapes) drawShape(sh, k);
}

const makeTex = () => {
  const t = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, t);
  for (const [p, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, p, v);
  return t;
};
const paintTex = makeTex(), photoTex = makeTex();
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, bitmap);

const fs = `#version 300 es
precision highp float;
out vec4 outColor;
uniform vec2 u_resolution;
uniform sampler2D u_paintTex, u_photoTex;
uniform vec4 u_rectA, u_rectB; // x, y, w, h in pixels, origin top-left
uniform float u_showB, u_px;
float boxSd(vec2 p, vec4 r) { vec2 c = r.xy + 0.5 * r.zw; vec2 d = abs(p - c) - 0.5 * r.zw; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
vec3 panel(vec3 bg, vec2 p, vec4 r, sampler2D tex) {
  float d = boxSd(p, r);
  bg *= 1.0 - 0.55 * exp(-max(d, 0.0) / (14.0 * u_px)) * step(0.0, d); // soft drop shadow
  if (d < 0.0) bg = texture(tex, (p - r.xy) / r.zw).rgb;
  return bg;
}
void main() {
  vec2 p = vec2(gl_FragCoord.x, u_resolution.y - gl_FragCoord.y);
  vec2 q = gl_FragCoord.xy / u_resolution - 0.5;
  vec3 c = mix(vec3(0.115, 0.112, 0.105), vec3(0.06, 0.06, 0.058), smoothstep(0.1, 0.9, length(q)));
  c = panel(c, p, u_rectA, u_paintTex);
  if (u_showB > 0.5) c = panel(c, p, u_rectB, u_photoTex);
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, {
  W, H, prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs), paintTex, photoTex,
  search, addShape, reset, redrawAll, drawShape, paint, st, layoutKey: "", rectA: [0, 0, 1, 1], rectB: [0, 0, 1, 1],
});
reset();

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
if (u.u_restart) s.reset();

// Layout: the painting alone, or painting + target side by side (or stacked in portrait), whichever is larger.
const show = !!u.u_target, img = s.W / s.H, m = Math.round(Math.min(w, h) * 0.05);
const fit = (bw, bh) => (bw / bh > img ? [bh * img, bh] : [bw, bw / img]);
let A, B = [0, 0, 1, 1];
if (!show) {
  const [fw, fh] = fit(w - 2 * m, h - 2 * m);
  A = [(w - fw) / 2, (h - fh) / 2, fw, fh];
} else {
  const side = fit((w - 3 * m) / 2, h - 2 * m), stack = fit(w - 2 * m, (h - 3 * m) / 2);
  if (side[0] >= stack[0]) {
    const [fw, fh] = side, x0 = (w - 2 * fw - m) / 2, y0 = (h - fh) / 2;
    A = [x0, y0, fw, fh]; B = [x0 + fw + m, y0, fw, fh];
  } else {
    const [fw, fh] = stack, x0 = (w - fw) / 2, y0 = (h - 2 * fh - m) / 2;
    A = [x0, y0, fw, fh]; B = [x0, y0 + fh + m, fw, fh];
  }
}
A = A.map(Math.round); B = B.map(Math.round);
const pw = Math.max(16, Math.min(2048, A[2])), ph = Math.max(16, Math.round(pw / img));
const key = `${pw}x${ph}`;
if (ctx.resized || key !== s.layoutKey || s.replay) { s.layoutKey = key; s.replay = false; s.redrawAll(pw, ph); s.dirty = true; }

// Search within a time budget per frame; shapes per second sets how much credit accrues.
const MAX_SHAPES = 5000;
if (s.shapes.length < MAX_SHAPES) {
  s.credit = Math.min(s.credit + u.u_rate * Math.min(ctx.dt, 0.1), 3);
  const t0 = performance.now();
  let n = 0;
  while (s.credit >= 1) {
    s.gen ??= s.search(u.u_shape | 0, u.u_alpha | 0);
    const r = s.gen.next();
    if (r.done) {
      s.gen = null; s.credit -= 1;
      s.drawShape(s.addShape(r.value.s, r.value.alpha), s.paint.width / s.W);
      s.dirty = true;
      if (s.shapes.length >= MAX_SHAPES) break;
    }
    if ((++n & 15) === 0 && performance.now() - t0 > 9) break;
  }
}
if (s.dirty) {
  s.dirty = false;
  gl.bindTexture(gl.TEXTURE_2D, s.paintTex);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, s.paint);
}
ctx.publish("shapes", s.shapes.length);
ctx.publish("similarity %", Math.round((1 - s.st.score) * 1000) / 10);

gl.useProgram(s.prog);
ctx.utils.bindTexture(s.prog, "u_paintTex", s.paintTex, 0);
ctx.utils.bindTexture(s.prog, "u_photoTex", s.photoTex, 1);
ctx.utils.drawFullscreen(s.prog, { u_rectA: A, u_rectB: B, u_showB: show ? 1 : 0, u_px: Math.max(1, h / 1000) });
